    f_min = [float('inf')] * n
    for i in range(n):
        prev_max = 0
        if i >= 1: prev_max = max(prev_max, f_max[i-1])
        if i >= 2: prev_max = max(prev_max, f_max[i-2])
        f_max[i] = a[i] + prev_max
        prev_min = 0
        if i >= 1: prev_min = min(prev_min, f_min[i-1])
        if i >= 2: prev_min = min(prev_min, f_min[i-2])
        f_min[i] = a[i] + prev_min
    return max(max(f_max), -min(f_min))

